#!/usr/bin/python3
import os,sys,signal,termios,json
root=os.environ['NARO_FIXTURE_ROOT']
assert os.path.realpath(root)==root and '/TEST-TINY-TERM-' in root and root.endswith('/fx')
before=termios.tcgetattr(0)
child=os.fork()
if child==0:os.execv(os.environ['NARO_FAULT_BINARY'],['nano',*sys.argv[1:]])
def forward(sig,frame):
 try:os.kill(child,sig)
 except ProcessLookupError:pass
for sig in [signal.SIGHUP,signal.SIGTERM]:signal.signal(sig,forward)
_,status=os.waitpid(child,0)
with open(root+'/home/terminal.json','w') as f:json.dump({'restored':termios.tcgetattr(0)==before},f);f.write('\n')
sys.exit(os.waitstatus_to_exitcode(status))

